$ErrorActionPreference='Stop'
$out='tmp/online-ch2-b4-next-strong-convex-freeze-20261011/application'
function Bind([string]$s){$f=Get-Item -LiteralPath $s;[ordered]@{path=$s;sha256=(Get-FileHash $s -Algorithm SHA256).Hash.ToLower();bytes=$f.Length}}
function Save([string]$n,$o){$p=Join-Path (Get-Location) "$out/$n";if(Test-Path $p){throw 'Create only'};[IO.File]::WriteAllText($p,($o|ConvertTo-Json -Depth 90)+"`n",[Text.UTF8Encoding]::new($false))}
$audit='tmp/online-ch2-b4-next-strong-convex-freeze-audit-20261011/freeze-application-review-v1.json'
if((Bind $audit).sha256 -ne '2b9940999f390808e0f42f14bd63a31a355a0e226f021b41b740670656a31979'){throw 'audit mismatch'}
$p=Get-Content "$out/canonical-freeze-application-proposal-v1.json" -Raw|ConvertFrom-Json -AsHashtable
$historical=@(Get-ChildItem $out -File | Where-Object Name -Match '-v1\.' | ForEach-Object {Bind "$out/$($_.Name)"})
$rows=[Collections.Generic.List[object]]::new();foreach($r in $p.archival_rows){$rows.Add($r)}
foreach($b in @($historical)+@(Bind $audit)){$rows.Add([ordered]@{source=$b.path;destination=($p.canonical_run+'/archive/'+$b.path);sha256=$b.sha256;bytes=$b.bytes;purpose='Exact historical application V1/review repair; retained without rewriting'})}
$p.status='V2_UNEXECUTED_SAFETY_REPAIR_PROPOSAL_PARENT_AUTHORIZATION_REQUIRED'
$p.successor_of=Bind "$out/canonical-freeze-application-proposal-v1.json"
$p.repair_review=Bind $audit
$p.observed_current_head=(git rev-parse HEAD).Trim();if($LASTEXITCODE -ne 0){throw 'git failed'}
$p.archival_rows=@($rows.ToArray())
$p.emitter=Bind "$out/emit-canonical-freeze-v2.ps1"
$p.authorization_protocol=[ordered]@{action='AUTHORIZE_CANONICAL_FREEZE_ONLY';proposal_sha256='Parent fills actual reviewed proposal SHA256';emitter_sha256=$p.emitter.sha256;source_head='Actual clean HEAD accepted by maintenance final receipt; may differ from historical prepared_head';maintenance_final_receipt='REQUIRED exact path/sha256; head_json_pointer; verdict_json_pointer; success_verdict; final_review_sha256_json_pointer';maintenance_final_review='REQUIRED exact path/sha256; head_json_pointer; verdict_json_pointer; success_verdict';freeze_application_review='REQUIRED exact path/sha256; verdict_json_pointer; success_verdict; proposal_sha256_json_pointer; emitter_sha256_json_pointer';success_verdict_policy='Exact authored verdict matching ^(ACCEPTED|PASS)(_|$), rejecting PENDING/STRUCTURAL/REPAIR/CONDITIONAL/ELIGIBLE/NOT_ACCEPTED';additional_archive_bindings='Optional explicit path/sha256/destination rows restricted to canonical RUN/authorized-review-increments; every row archived in execution receipt';not_an_authorization=$true;maintenance_acceptance_supplied=$false}
$p.safety='All git exit codes checked; every normalized destination restricted to hard-coded reviewed DOC/RUN; all existing destination ancestors up to root reject reparse points before and during copy; copy overwrite=false; receipt FileMode.CreateNew; no deletes/rollback/force; failure retains partial artifacts for inspection.'
$p.dynamic_archive_policy='At execution only, hash-bound independently reviewed maintenance final acceptance and independent maintenance final review (both same actual HEAD), independent successful freeze application review (binds exact proposal/emitter), explicit future review increments, parent authorization, proposal and emitter are archived. No acceptance evidence fabricated during preparation.'
Save 'canonical-freeze-application-proposal-v2.json' $p
Save 'application-repair-response-v2.json' ([ordered]@{status='APPLIED_AWAITING_DISTINCT_REREVIEW_NO_EXECUTION';audit=Bind $audit;proposal=Bind "$out/canonical-freeze-application-proposal-v2.json";emitter=Bind "$out/emit-canonical-freeze-v2.ps1";repairs=@([ordered]@{id='AUTH-RECEIPT';resolution='Require exact final receipt and independent review hashes, successful final verdicts, same actual HEAD, final receipt binding independent review hash; archive all exact evidence. Also require separate application review pinning proposal/emitter.'},[ordered]@{id='EMITTER-PIN';resolution='Parent authorization and independent application review must both bind actual executing emitter SHA; persist in atomic receipt'},[ordered]@{id='PHYSICAL-PATH-CREATEONLY';resolution='Hard-coded normalized approved subtrees; reject all existing reparse ancestors; recheck before copy; FileMode.CreateNew receipt; all Git exits checked'});historical_v1_bindings=$historical;original_archival_rows_retained=126;total_static_rows=$rows.Count;source_header_contract_math_changed=$false;historical_prepared_e7_preserved=$true;maintenance_final_acceptance='NOT SUPPLIED; pending parent gates/review';executed=$false;BODY=$false;tracked_edits=$false})
$errors=$null;$tokens=$null;[System.Management.Automation.Language.Parser]::ParseFile((Join-Path (Get-Location) "$out/emit-canonical-freeze-v2.ps1"),[ref]$tokens,[ref]$errors)|Out-Null;if($errors.Count){throw ($errors|Out-String)}
foreach($r in $rows){$b=Bind $r.source;if($b.sha256 -ne $r.sha256 -or $b.bytes -ne $r.bytes){throw 'source changed'}}
foreach($b in $historical){if((Bind $b.path).sha256 -ne $b.sha256){throw 'history changed'}}
$schema=Get-Content "$out/native-contribution-manifest-draft-v1.json" -Raw|Test-Json -SchemaFile docs/contribution-contract.schema.json
Save 'application-verification-v2.json' ([ordered]@{status='STATIC_PREPARATION_CHECKS_ONLY';static_archive_rows_verified=$rows.Count;historical_V1_preserved=$true;emitter_parser_errors=0;native_draft_schema_valid=$schema;emitter_executed=$false;source_head=$p.observed_current_head;git_status=@(git status --porcelain=v1);receipt_existence='Maintenance final receipt deliberately not supplied';dynamic_authorization_execution_checks='NOT RUN';BODY=$false})
Save 'application-artifact-manifest-v2.json' (@(Get-ChildItem $out -File|Where-Object Name -Match '-v2\.'|ForEach-Object {Bind "$out/$($_.Name)"}))
Get-ChildItem $out -File|Where-Object Name -Match 'proposal-v2|emitter-v2|emit-canonical-freeze-v2|repair-response-v2'|ForEach-Object {Bind "$out/$($_.Name)"}|ConvertTo-Json
